<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { eliminarCisterna, eliminarMantenimiento, guardarCisterna, guardarMantenimiento, listarCisternas, listarMantenimientos } from '../services/cisternas'
import type { Cisterna, CisternaPayload, MantenimientoCisterna, OpcionCisterna } from '../interfaces/cisternas.interface'
const records=ref<Cisterna[]>([]),offices=ref<OpcionCisterna[]>([]),people=ref<OpcionCisterna[]>([]),states=ref<Record<number,string>>({}),properties=ref<Record<number,string>>({}),fuels=ref<Record<number,string>>({}),vehicleTypes=ref<Record<number,string>>({}),reasons=ref<Record<number,string>>({}),maintenances=ref<MantenimientoCisterna[]>([]),query=ref(''),date=ref(new Date().toISOString().slice(0,10)),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),unitModal=ref(false),maintenanceModal=ref(false),historyModal=ref(false),editing=ref<number|null>(null),maintenanceEditing=ref<number|null>(null),current=ref<Cisterna|null>(null),page=ref(1),lastPage=ref(1),total=ref(0),totals=reactive({libres:0,programadas:0,mantenimiento:0})
const form=reactive<CisternaPayload>({placa:'',vin:'',marca:'',modelo:'',capacidad:null,fabricacion:null,combustible_id:null,tipo_vehiculo_id:null,imei:'',celular:'',estado_id:1,propiedad_id:null,oficina_id:null,ubicacion:'',observacion:'',conductor_id:null,ayudante_id:null}),maintenance=reactive({motivo_id:null as number|null,detalle:'',fecha_desde:'',fecha_hasta:''})
async function load(target=1){loading.value=true;error.value='';try{const r=await listarCisternas(query.value,date.value,target);records.value=r.data;offices.value=r.oficinas;people.value=r.personas;states.value=r.estados;properties.value=r.propiedades;fuels.value=r.combustibles;vehicleTypes.value=r.tipos_vehiculo;reasons.value=r.motivos_mantenimiento;page.value=r.current_page;lastPage.value=r.last_page;total.value=r.total;Object.assign(totals,r.totales)}catch(e){error.value=message(e)}finally{loading.value=false}}
function openUnit(item?:Cisterna){editing.value=item?.id??null;Object.assign(form,item?{placa:item.placa,vin:item.vin,marca:item.marca,modelo:item.modelo,capacidad:item.capacidad,fabricacion:item.fabricacion,combustible_id:Number(Object.keys(fuels.value).find(k=>fuels.value[Number(k)]===item.combustible))||null,tipo_vehiculo_id:Number(Object.keys(vehicleTypes.value).find(k=>vehicleTypes.value[Number(k)]===item.tipo_vehiculo))||null,imei:item.imei||'',celular:item.celular||'',estado_id:item.estado_id,propiedad_id:item.propiedad_id,oficina_id:item.oficina_id,ubicacion:item.ubicacion,observacion:item.observacion,conductor_id:item.conductor_id,ayudante_id:item.ayudante_id}:{placa:'',vin:'',marca:'',modelo:'',capacidad:null,fabricacion:null,combustible_id:null,tipo_vehiculo_id:3,imei:'',celular:'',estado_id:1,propiedad_id:null,oficina_id:null,ubicacion:'',observacion:'',conductor_id:null,ayudante_id:null});unitModal.value=true}
async function saveUnit(){if(!form.placa.trim()||!form.vin.trim()||!form.marca.trim()||!form.modelo.trim()||!form.capacidad||!form.fabricacion||!form.combustible_id||!form.tipo_vehiculo_id||!form.estado_id||!form.propiedad_id||!form.oficina_id||!form.ubicacion.trim()||!form.observacion.trim()||!form.conductor_id){error.value='Complete todos los campos obligatorios de la unidad.';return}if(form.imei&&!/^\d{15}$/.test(form.imei)){error.value='El IMEI debe tener exactamente 15 dígitos.';return}saving.value=true;try{await guardarCisterna(form,editing.value??undefined);unitModal.value=false;success.value=`Cisterna ${editing.value?'actualizada':'registrada'} correctamente.`;await load(page.value)}catch(e){error.value=message(e)}finally{saving.value=false}}
async function openHistory(item:Cisterna){current.value=item;loading.value=true;try{maintenances.value=await listarMantenimientos(item.id);historyModal.value=true}catch(e){error.value=message(e)}finally{loading.value=false}}
function openMaintenance(item:Cisterna,row?:MantenimientoCisterna){current.value=item;maintenanceEditing.value=row?.id??null;Object.assign(maintenance,row?{motivo_id:row.motivo_id,detalle:row.detalle,fecha_desde:row.fecha_desde,fecha_hasta:row.fecha_hasta}:{motivo_id:null,detalle:'',fecha_desde:'',fecha_hasta:''});historyModal.value=false;maintenanceModal.value=true}
async function saveMaintenance(){if(!current.value||!maintenance.motivo_id||!maintenance.detalle.trim()||!maintenance.fecha_desde||!maintenance.fecha_hasta){error.value='Complete todos los datos del mantenimiento.';return}if(maintenance.fecha_hasta<maintenance.fecha_desde){error.value='La fecha final no puede ser anterior a la inicial.';return}saving.value=true;try{await guardarMantenimiento(current.value.id,maintenance,maintenanceEditing.value??undefined);maintenanceModal.value=false;success.value='Mantenimiento guardado correctamente.';await load(page.value)}catch(e){error.value=message(e)}finally{saving.value=false}}
async function removeUnit(item:Cisterna){if(!confirm(`¿Eliminar la cisterna ${item.placa}?`))return;try{await eliminarCisterna(item.id);success.value='Cisterna eliminada.';await load(page.value)}catch(e){error.value=message(e)}}
async function removeMaintenance(row:MantenimientoCisterna){if(!current.value||!confirm('¿Eliminar este mantenimiento?'))return;try{await eliminarMantenimiento(current.value.id,row.id);maintenances.value=await listarMantenimientos(current.value.id);success.value='Mantenimiento eliminado.'}catch(e){error.value=message(e)}}
const message=(e:unknown)=>e instanceof Error?e.message:'No se pudo completar la operación.'
onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Operaciones / Gestión de Cisternas / Unidades</nav><header class="hero"><div class="mark">CI</div><div><small>DANA · GESTIÓN DE CISTERNAS</small><h1>Unidades móviles</h1><p>Administra cisternas, disponibilidad, personal y mantenimiento.</p></div><button @click="openUnit()">+ Registrar unidad</button></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash">{{error}}</p><section class="summary"><article><small>UNIDADES ACTIVAS</small><b>{{total}}</b></article><article><small>LIBRES EN LA FECHA</small><b>{{totals.libres}}</b></article><article><small>EN PROGRAMACIÓN</small><b>{{totals.programadas}}</b></article><article><small>EN MANTENIMIENTO</small><b>{{totals.mantenimiento}}</b></article></section><form class="filters" @submit.prevent="load(1)"><label>Fecha de disponibilidad<input v-model="date" type="date"></label><label>Buscar unidad<input v-model.trim="query" placeholder="Placa, VIN, marca, modelo o capacidad"></label><button>Buscar</button></form><div v-if="loading" class="empty">Cargando unidades…</div><div v-else-if="!records.length" class="empty">No se encontraron cisternas.</div><section v-else class="cards"><article v-for="item in records" :key="item.id" :class="{busy:item.programada_hoy}"><header><div class="truck">▰</div><div><small>PLACA DE UNIDAD</small><h2>{{item.placa}}</h2></div><span>{{item.programada_hoy?'EN PROGRAMACIÓN':'LIBRE'}}</span></header><div class="vehicle"><b>{{item.marca}} {{item.modelo}}</b><span>{{item.fabricacion}} · {{item.capacidad}} m³ · {{item.combustible}}</span></div><dl><div><dt>Estado</dt><dd>{{item.estado}}</dd></div><div><dt>Conductor</dt><dd>{{item.conductor||'—'}}</dd></div><div><dt>Ayudante</dt><dd>{{item.ayudante||'—'}}</dd></div><div><dt>GPS</dt><dd>{{item.gps?'Habilitado':'Sin GPS'}}</dd></div><div><dt>Ubicación</dt><dd>{{item.ubicacion}}</dd></div></dl><button class="maintenance-count" @click="openHistory(item)">{{item.mantenimientos_count?`${item.mantenimientos_count} mantenimiento(s)`:'Sin mantenimientos'}}</button><footer><button class="edit" :disabled="item.programada_hoy" @click="openUnit(item)">Modificar</button><button class="maintain" :disabled="item.programada_hoy" @click="openMaintenance(item)">Mantenimiento</button><button class="delete" :disabled="item.programada_hoy" @click="removeUnit(item)">Eliminar</button></footer></article></section><footer v-if="lastPage>1" class="pager"><button :disabled="page===1" @click="load(page-1)">Anterior</button><span>Página {{page}} de {{lastPage}}</span><button :disabled="page===lastPage" @click="load(page+1)">Siguiente</button></footer>
<div v-if="unitModal" class="backdrop" @mousedown.self="unitModal=false"><form class="dialog large" @submit.prevent="saveUnit"><header><div><small>GESTIÓN DE ACTIVOS</small><h2>{{editing?'Modificar':'Registrar'}} unidad móvil</h2></div><button type="button" @click="unitModal=false">×</button></header><h3>Datos patrimoniales</h3><div class="fields"><label>Propiedad *<select v-model="form.propiedad_id"><option :value="null">Seleccione</option><option v-for="(name,key) in properties" :key="key" :value="Number(key)">{{name}}</option></select></label><label>Estado *<select v-model="form.estado_id"><option v-for="(name,key) in states" :key="key" :value="Number(key)">{{name}}</option></select></label><label>Oficina *<select v-model="form.oficina_id"><option :value="null">Seleccione</option><option v-for="item in offices" :key="item.id" :value="item.id">{{item.nombre}}</option></select></label><label>Ubicación *<input v-model="form.ubicacion" maxlength="100"></label><label class="wide">Observación *<textarea v-model="form.observacion" rows="2" maxlength="200"></textarea></label></div><h3>Datos vehiculares</h3><div class="fields"><label>Placa *<input v-model="form.placa" maxlength="45"></label><label>VIN *<input v-model="form.vin" maxlength="45"></label><label>Marca *<input v-model="form.marca" maxlength="45"></label><label>Modelo *<input v-model="form.modelo" maxlength="45"></label><label>Capacidad (m³) *<input v-model.number="form.capacidad" type="number" min="1"></label><label>Año fabricación *<input v-model.number="form.fabricacion" type="number" min="1900" max="2100"></label><label>Tipo vehículo *<select v-model="form.tipo_vehiculo_id"><option :value="null">Seleccione</option><option v-for="(name,key) in vehicleTypes" :key="key" :value="Number(key)">{{name}}</option></select></label><label>Combustible *<select v-model="form.combustible_id"><option :value="null">Seleccione</option><option v-for="(name,key) in fuels" :key="key" :value="Number(key)">{{name}}</option></select></label><label>Celular GPS<input v-model="form.celular"></label><label>IMEI<input v-model="form.imei" maxlength="15" inputmode="numeric"></label><label>Conductor *<select v-model="form.conductor_id"><option :value="null">Seleccione</option><option v-for="item in people" :key="item.id" :value="item.id">{{item.nombre}}</option></select></label><label>Ayudante<select v-model="form.ayudante_id"><option :value="null">Sin ayudante</option><option v-for="item in people" :key="item.id" :value="item.id">{{item.nombre}}</option></select></label></div><footer><button type="button" class="soft" @click="unitModal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':editing?'Actualizar':'Registrar unidad'}}</button></footer></form></div>
<div v-if="maintenanceModal" class="backdrop" @mousedown.self="maintenanceModal=false"><form class="dialog" @submit.prevent="saveMaintenance"><header><div><small>UNIDAD {{current?.placa}}</small><h2>{{maintenanceEditing?'Modificar':'Registrar'}} mantenimiento</h2></div><button type="button" @click="maintenanceModal=false">×</button></header><label>Motivo *<select v-model="maintenance.motivo_id"><option :value="null">Seleccione</option><option v-for="(name,key) in reasons" :key="key" :value="Number(key)">{{name}}</option></select></label><label>Detalle *<textarea v-model="maintenance.detalle" rows="3"></textarea></label><div class="fields"><label>Desde *<input v-model="maintenance.fecha_desde" type="date"></label><label>Hasta *<input v-model="maintenance.fecha_hasta" type="date"></label></div><footer><button type="button" class="soft" @click="maintenanceModal=false">Cancelar</button><button :disabled="saving">Guardar mantenimiento</button></footer></form></div><div v-if="historyModal" class="backdrop" @mousedown.self="historyModal=false"><section class="dialog history"><header><div><small>UNIDAD {{current?.placa}}</small><h2>Historial de mantenimientos</h2></div><button @click="historyModal=false">×</button></header><article v-for="row in maintenances" :key="row.id"><div><b>{{row.motivo}}</b><span>{{row.fecha_desde}} — {{row.fecha_hasta}}</span><p>{{row.detalle}}</p></div><button @click="openMaintenance(current!,row)">Editar</button><button class="delete" @click="removeMaintenance(row)">Eliminar</button></article><p v-if="!maintenances.length">No hay mantenimientos registrados.</p></section></div></div></template>
